FD='src.book.reis-housley-fundamentals-data-engineering'; DD='src.book.kleppmann-ddia.1e'; AP='src.book.geewax-api-design-patterns.1e'; MS='src.web.microsoft-sql-server-cdc'; AI='src.web.airbyte-incremental-append-deduped'; GA='src.standard.google-aip-158-pagination'; HT='src.web.rfc9110-http-semantics'
